  (883,'govt_technical','mach-concept','concept',1,'सरल मशीनें — SSC JE / RRB JE',$j${"note":"JE में MA, VR और दक्षता का संबंध अक्सर पूछा जाता है।","text":"यांत्रिक लाभ MA = भार / प्रयास। वेग अनुपात VR = प्रयास की दूरी / भार की दूरी। दक्षता η = (MA / VR) × 100%। लीवर, पुली, झुका तल, पेंच और पहिया-धुरी सरल मशीनें हैं।"}$j$),
  (883,'govt_technical','mach-formula','formula',2,'दक्षता का सूत्र',$j${"formula":"η = (MA / VR) × 100%","explanation":"MA = भार / प्रयास, VR = प्रयास की दूरी / भार की दूरी · आदर्श मशीन में η = 100%"}$j$),
  (883,'govt_technical','mach-example','example',3,'Numerical (JE style)',$j${"question":"500 N भार 100 N प्रयास से उठता है, और प्रयास 6 m दूरी तक चलता है जबकि भार 1 m उठता है। MA, VR और η निकालो।","solution":"MA = 500/100 = 5; VR = 6/1 = 6; η = 5/6 × 100 ≈ 83.3%","answer":"MA = 5, η ≈ 83.3%"}$j$),
  (883,'govt_technical','mach-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"आदर्श मशीन की दक्षता कितनी होती है?","options":["100%","50%","0%","200%"],"answer":0,"explanation":"आदर्श मशीन में कोई ऊर्जा नष्ट नहीं होती, इसलिए η = 100%।"},{"q":"यदि MA = 4 और VR = 8 हो तो दक्षता कितनी है?","options":["50%","25%","200%","100%"],"answer":0,"explanation":"η = (4/8) × 100 = 50%।"}]}$j$),
  (883,'govt_basic','mach-concept','concept',1,'सरल मशीनें',$j${"note":"परीक्षा में सरल मशीनों के नाम और उदाहरण पूछे जाते हैं।","text":"सरल मशीन बल की दिशा या परिमाण बदलकर काम आसान करती है। लीवर, पुली, झुका तल, पेंच और पहिया-धुरी इसके उदाहरण हैं। मशीन ऊर्जा नहीं बनाती, केवल काम आसान करती है।"}$j$),
  (883,'govt_basic','mach-formula','formula',2,'यांत्रिक लाभ',$j${"formula":"MA = भार / प्रयास","explanation":"MA = यांत्रिक लाभ (बिना इकाई), भार और प्रयास दोनों न्यूटन (N) में"}$j$),
  (883,'govt_basic','mach-example','example',3,'उदाहरण',$j${"question":"300 N भार उठाने के लिए 60 N प्रयास लगाया गया। MA कितना है?","solution":"MA = 300 / 60 = 5","answer":"5"}$j$),
