  -- 885 Matter & Its States
  (885,'govt_technical','matt-concept','concept',1,'पदार्थ की अवस्थाएँ — SSC JE / RRB JE',$j${"note":"JE में घनत्व का SI मात्रक kg/m³ और बॉयल का नियम अक्सर पूछा जाता है।","text":"पदार्थ की तीन अवस्थाएँ: ठोस, द्रव, गैस। घनत्व ρ = m/V। अवस्था परिवर्तन में अवशोषित या मुक्त ऊष्मा को गुप्त ऊष्मा L = Q/m कहते हैं। बॉयल का नियम: स्थिर ताप पर PV = स्थिर।"}$j$),
  (885,'govt_technical','matt-formula','formula',2,'घनत्व का सूत्र',$j${"formula":"ρ = m / V","explanation":"ρ = घनत्व (kg/m³), m = द्रव्यमान (kg), V = आयतन (m³) · 1 g/cm³ = 1000 kg/m³"}$j$),
  (885,'govt_technical','matt-example','example',3,'Numerical (JE style)',$j${"question":"2 kg द्रव्यमान का आयतन 0.001 m³ है। घनत्व कितना है?","solution":"ρ = 2 / 0.001 = 2000 kg/m³","answer":"2000 kg/m³"}$j$),
  (885,'govt_technical','matt-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"बर्फ के पिघलने की गुप्त ऊष्मा का लगभग मान क्या है?","options":["3.36×10⁵ J/kg","4186 J/kg","2.26×10⁶ J/kg","1000 J/kg"],"answer":0,"explanation":"बर्फ की गलन गुप्त ऊष्मा लगभग 3.36×10⁵ J/kg है।"},{"q":"स्थिर ताप पर गैस के दाब और आयतन (PV) का गुणनफल कैसा रहता है?","options":["स्थिर रहता है","बढ़ता है","घटता है","शून्य हो जाता है"],"answer":0,"explanation":"बॉयल के नियम के अनुसार स्थिर ताप पर PV स्थिर रहता है।"}]}$j$),
  (885,'govt_basic','matt-concept','concept',1,'पदार्थ की अवस्थाएँ',$j${"note":"परीक्षा में पदार्थ की तीन अवस्थाओं के गुण पूछे जाते हैं।","text":"पदार्थ तीन अवस्थाओं में मिलता है। ठोस का आकार और आयतन निश्चित होता है। द्रव का आयतन निश्चित होता है, पर आकार बर्तन जैसा होता है। गैस का न आकार निश्चित होता है न आयतन। ताप बढ़ाने पर ठोस, द्रव और फिर गैस बनता है।"}$j$),
  (885,'govt_basic','matt-formula','formula',2,'घनत्व',$j${"formula":"ρ = m / V","explanation":"घनत्व = द्रव्यमान / आयतन; मात्रक kg/m³ या g/cm³"}$j$),
  (885,'govt_basic','matt-example','example',3,'उदाहरण',$j${"question":"10 g पदार्थ का आयतन 5 cm³ है। घनत्व कितना है?","solution":"ρ = 10 / 5 = 2 g/cm³","answer":"2 g/cm³"}$j$),
  (885,'govt_basic','matt-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"किस अवस्था का आयतन और आकार दोनों निश्चित होते हैं?","options":["ठोस","द्रव","गैस","प्लाज़्मा"],"answer":0,"explanation":"ठोस का आयतन और आकार दोनों निश्चित होते हैं।"},{"q":"पानी का घनत्व लगभग कितना है?","options":["1 g/cm³","10 g/cm³","0.1 g/cm³","100 g/cm³"],"answer":0,"explanation":"पानी का घनत्व लगभग 1 g/cm³ (1000 kg/m³) है।"}]}$j$),
  (885,null,'matt-diagram','svg',5,'पदार्थ के कण',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><g fill='#60a5fa'><circle cx='40' cy='30' r='6'/><circle cx='60' cy='30' r='6'/><circle cx='50' cy='50' r='6'/><circle cx='70' cy='50' r='6'/></g><g fill='#14b8a6'><circle cx='130' cy='30' r='6'/><circle cx='165' cy='45' r='6'/><circle cx='140' cy='70' r='6'/></g><g fill='#f59e0b'><circle cx='230' cy='25' r='6'/><circle cx='260' cy='70' r='6'/><circle cx='210' cy='85' r='6'/></g><text x='50' y='115' text-anchor='middle' fill='#64748b' font-size='11'>ठोस</text><text x='150' y='115' text-anchor='middle' fill='#64748b' font-size='11'>द्रव</text><text x='240' y='115' text-anchor='middle' fill='#64748b' font-size='11'>गैस</text></svg>","caption":"ठोस में कण पास-पास बंधे, द्रव में ढीले और गैस में सबसे दूर होते हैं"}$j$),
  -- 886 Atomic Structure
  (886,'govt_technical','atom-concept','concept',1,'परमाणु संरचना — SSC JE / RRB JE',$j${"note":"JE/Chem में इलेक्ट्रॉन विन्यास और समस्थानिक अक्सर पूछे जाते हैं।","text":"परमाणु में प्रोटॉन (+1), न्यूट्रॉन (0) और इलेक्ट्रॉन (−1) होते हैं। परमाणु क्रमांक Z = प्रोटॉन की संख्या, द्रव्यमान संख्या A = प्रोटॉन + न्यूट्रॉन। K, L, M कोशों में अधिकतम इलेक्ट्रॉन 2n² होते हैं।"}$j$),
  (886,'govt_technical','atom-formula','formula',2,'द्रव्यमान संख्या',$j${"formula":"A = Z + n","explanation":"A = द्रव्यमान संख्या, Z = परमाणु क्रमांक (प्रोटॉन), n = न्यूट्रॉन · कोश में अधिकतम इलेक्ट्रॉन = 2n²"}$j$),
  (886,'govt_technical','atom-example','example',3,'Numerical (JE style)',$j${"question":"सोडियम का Z = 11 और A = 23 है। न्यूट्रॉन और इलेक्ट्रॉन कितने हैं?","solution":"n = 23 − 11 = 12; उदासीन परमाणु में इलेक्ट्रॉन = Z = 11","answer":"न्यूट्रॉन 12, इलेक्ट्रॉन 11"}$j$),
  (886,'govt_technical','atom-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"K कोश में अधिकतम कितने इलेक्ट्रॉन आ सकते हैं?","options":["2","8","18","32"],"answer":0,"explanation":"K कोश (n = 1) में अधिकतम 2×1² = 2 इलेक्ट्रॉन होते हैं।"},{"q":"जिन परमाणुओं का Z समान और A अलग हो, वे क्या कहलाते हैं?","options":["समस्थानिक (isotopes)","समभारिक (isobars)","समावयवी","आयन"],"answer":0,"explanation":"समान Z और अलग A वाले परमाणु समस्थानिक कहलाते हैं।"}]}$j$),
  (886,'govt_basic','atom-concept','concept',1,'परमाणु',$j${"note":"परीक्षा में प्रोटॉन, न्यूट्रॉन, इलेक्ट्रॉन के आवेश पूछे जाते हैं।","text":"हर पदार्थ परमाणुओं से बना है। केंद्र (नाभिक) में प्रोटॉन और न्यूट्रॉन होते हैं, और बाहर इलेक्ट्रॉन घूमते हैं। परमाणु उदासीन होता है क्योंकि प्रोटॉन और इलेक्ट्रॉन बराबर होते हैं।"}$j$),
  (886,'govt_basic','atom-formula','formula',2,'परमाणु क्रमांक',$j${"formula":"Z = प्रोटॉन की संख्या","explanation":"A = Z + न्यूट्रॉन; उदासीन परमाणु में इलेक्ट्रॉन = Z"}$j$),
  (886,'govt_basic','atom-example','example',3,'उदाहरण',$j${"question":"ऑक्सीजन का Z = 8 और A = 16 है। न्यूट्रॉन कितने हैं?","solution":"16 − 8 = 8","answer":"8"}$j$),
  (886,'govt_basic','atom-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"परमाणु में किसका आवेश ऋणात्मक होता है?","options":["इलेक्ट्रॉन","प्रोटॉन","न्यूट्रॉन","नाभिक"],"answer":0,"explanation":"इलेक्ट्रॉन पर ऋणात्मक आवेश होता है।"},{"q":"परमाणु का नाभिक किससे बना है?","options":["प्रोटॉन और न्यूट्रॉन","इलेक्ट्रॉन और प्रोटॉन","केवल इलेक्ट्रॉन","केवल न्यूट्रॉन"],"answer":0,"explanation":"नाभिक में प्रोटॉन और न्यूट्रॉन होते हैं।"}]}$j$),
