  -- 887 Periodic Table
  (887,'govt_technical','peri-concept','concept',1,'आवर्त सारणी — SSC JE / RRB JE',$j${"note":"JE/Chem में वर्ग और आवर्त पहचानना अक्सर पूछा जाता है।","text":"आधुनिक आवर्त नियम: तत्वों के गुण परमाणु क्रमांक के आवर्ती होते हैं। सारणी में 18 वर्ग (group) और 7 आवर्त (period) होते हैं। आवर्त संख्या = कोशों की संख्या; वर्ग 13–18 के लिए संयोजकता इलेक्ट्रॉन = वर्ग − 10।"}$j$),
  (887,'govt_technical','peri-formula','formula',2,'आवर्त और वर्ग का नियम',$j${"formula":"संयोजकता इलेक्ट्रॉन = वर्ग − 10 (वर्ग 13–18 के लिए)","explanation":"आवर्त = इलेक्ट्रॉन वाले कोशों की संख्या · वर्ग 1–2 में संयोजकता इलेक्ट्रॉन = वर्ग संख्या"}$j$),
  (887,'govt_technical','peri-example','example',3,'Numerical (JE style)',$j${"question":"क्लोरीन का Z = 17 है। इलेक्ट्रॉन विन्यास 2, 8, 7 है। इसका आवर्त और वर्ग कितना है?","solution":"3 कोश ⇒ आवर्त 3; संयोजकता इलेक्ट्रॉन 7 ⇒ वर्ग = 7 + 10 = 17","answer":"आवर्त 3, वर्ग 17"}$j$),
  (887,'govt_technical','peri-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"वर्ग 18 के तत्व क्या कहलाते हैं?","options":["उत्कृष्ट गैसें (noble gases)","क्षार धातुएँ","हैलोजन","संक्रमण धातुएँ"],"answer":0,"explanation":"वर्ग 18 के तत्व उत्कृष्ट गैसें हैं, जो लगभग निष्क्रिय होती हैं।"},{"q":"आवर्त सारणी में कुल आवर्त (periods) कितने हैं?","options":["7","8","18","9"],"answer":0,"explanation":"आवर्त सारणी में 7 आवर्त होते हैं।"}]}$j$),
  (887,'govt_basic','peri-concept','concept',1,'आवर्त सारणी',$j${"note":"परीक्षा में वर्ग 1, 17, 18 के नाम पूछे जाते हैं।","text":"तत्वों को परमाणु क्रमांक के क्रम में रखा गया है। सारणी में ऊर्ध्व स्तंभ वर्ग और क्षैतिज पंक्ति आवर्त कहलाती है। एक ही वर्ग के तत्वों के गुण मिलते-जुलते होते हैं।"}$j$),
  (887,'govt_basic','peri-formula','formula',2,'प्रमुख वर्ग',$j${"formula":"वर्ग 1 = क्षार धातुएँ, वर्ग 17 = हैलोजन, वर्ग 18 = उत्कृष्ट गैसें","explanation":"ये नाम परीक्षा में सबसे ज़्यादा पूछे जाते हैं"}$j$),
  (887,'govt_basic','peri-example','example',3,'उदाहरण',$j${"question":"सोडियम (Na) किस वर्ग में आता है?","solution":"सोडियम क्षार धातु है, इसलिए वर्ग 1 में आता है","answer":"वर्ग 1"}$j$),
  (887,'govt_basic','peri-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"सबसे क्रियाशील अधातुएँ किस वर्ग में आती हैं?","options":["हैलोजन (वर्ग 17)","उत्कृष्ट गैसें (वर्ग 18)","क्षार धातुएँ (वर्ग 1)","वर्ग 2"],"answer":0,"explanation":"हैलोजन (फ्लोरीन, क्लोरीन आदि) सबसे क्रियाशील अधातुएँ हैं।"},{"q":"उत्कृष्ट गैसें किस वर्ग में हैं?","options":["वर्ग 18","वर्ग 1","वर्ग 17","वर्ग 2"],"answer":0,"explanation":"उत्कृष्ट गैसें वर्ग 18 में हैं।"}]}$j$),
  (887,null,'peri-diagram','svg',5,'आवर्त सारणी का ढाँचा',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><g stroke='#64748b' fill='none'><rect x='20' y='20' width='20' height='20'/><rect x='40' y='20' width='20' height='20'/><rect x='240' y='20' width='20' height='20'/><rect x='20' y='40' width='20' height='20'/><rect x='240' y='40' width='20' height='20'/></g><rect x='20' y='20' width='20' height='20' fill='#60a5fa' opacity='0.6'/><rect x='240' y='20' width='20' height='20' fill='#14b8a6' opacity='0.6'/><text x='150' y='112' text-anchor='middle' fill='#64748b' font-size='11'>बाएँ: वर्ग 1 (क्षार) · दाएँ: वर्ग 18 (उत्कृष्ट गैसें)</text></svg>","caption":"आवर्त सारणी में वर्ग ऊर्ध्व स्तंभ और आवर्त क्षैतिज पंक्ति होती है"}$j$),
  -- 888 Chemical Bonding
  (888,'govt_technical','bond-concept','concept',1,'रासायनिक बंधन — SSC JE / RRB JE',$j${"note":"JE में आयनिक और सहसंयोजक बंधन का अंतर अक्सर पूछा जाता है।","text":"आयनिक बंधन में इलेक्ट्रॉन स्थानांतरित होते हैं (जैसे NaCl)। सहसंयोजक बंधन में इलेक्ट्रॉन साझा होते हैं (जैसे H₂O, CH₄)। अष्टक नियम: बाहरी कोश में 8 इलेक्ट्रॉन स्थिरता देते हैं (हाइड्रोजन में 2)।"}$j$),
  (888,'govt_technical','bond-formula','formula',2,'संयोजकता का सरल नियम',$j${"formula":"बंध संख्या ≈ 8 − संयोजकता इलेक्ट्रॉन (अधातुओं के लिए)","explanation":"यह सरल नियम अधातुओं (वर्ग 14–17) के लिए उपयोगी है · जैसे O के लिए 8 − 6 = 2 बंध"}$j$),
  (888,'govt_technical','bond-example','example',3,'Numerical (JE style)',$j${"question":"पानी (H₂O) में ऑक्सीजन कितने बंध बनाती है?","solution":"O के 6 संयोजकता इलेक्ट्रॉन हैं; अष्टक के लिए 2 और चाहिए ⇒ 2 बंध (दो H परमाणुओं से)","answer":"2 बंध"}$j$),
  (888,'govt_technical','bond-mcq','mcq',4,'JE MCQs',$j${"questions":[{"q":"NaCl में कौन सा बंधन है?","options":["आयनिक","सहसंयोजक","धात्विक","हाइड्रोजन"],"answer":0,"explanation":"NaCl में Na से इलेक्ट्रॉन Cl को स्थानांतरित होता है, इसलिए यह आयनिक बंधन है।"},{"q":"मीथेन (CH₄) में कार्बन कितने बंध बनाता है?","options":["4","2","3","1"],"answer":0,"explanation":"कार्बन के 4 संयोजकता इलेक्ट्रॉन हैं, इसलिए 4 बंध बनते हैं।"}]}$j$),
  (888,'govt_basic','bond-concept','concept',1,'रासायनिक बंधन',$j${"note":"परीक्षा में नमक और पानी के बंधन के प्रकार पूछे जाते हैं।","text":"परमाणु स्थिर होने के लिए बंधन बनाते हैं। आयनिक बंधन में इलेक्ट्रॉन दिए-लिए जाते हैं (जैसे नमक)। सहसंयोजक बंधन में इलेक्ट्रॉन साझा होते हैं (जैसे पानी, ऑक्सीजन गैस)।"}$j$),
  (888,'govt_basic','bond-formula','formula',2,'आयनिक बंधन',$j${"formula":"NaCl = Na⁺ + Cl⁻","explanation":"Na से एक इलेक्ट्रॉन निकलता है और Cl में जुड़ता है; Na⁺ और Cl⁻ विपरीत आवेश से जुड़ते हैं"}$j$),
  (888,'govt_basic','bond-example','example',3,'उदाहरण',$j${"question":"पानी का सूत्र H₂O है। एक अणु में कुल कितने परमाणु होते हैं?","solution":"2 हाइड्रोजन + 1 ऑक्सीजन = 3","answer":"3"}$j$),
  (888,'govt_basic','bond-mcq','mcq',4,'अभ्यास प्रश्न',$j${"questions":[{"q":"नमक (NaCl) किस प्रकार के बंधन से बनता है?","options":["आयनिक","सहसंयोजक","धात्विक","कोई नहीं"],"answer":0,"explanation":"नमक आयनिक बंधन से बनता है।"},{"q":"ऑक्सीजन गैस (O₂) में बंधन कैसा है?","options":["सहसंयोजक (दोहरा)","आयनिक","धात्विक","हाइड्रोजन"],"answer":0,"explanation":"O₂ में दो ऑक्सीजन परमाणु इलेक्ट्रॉन साझा करते हैं, इसलिए यह सहसंयोजक दोहरा बंधन है।"}]}$j$),
  (888,null,'bond-diagram','svg',5,'इलेक्ट्रॉन की साझेदारी',$j${"svg":"<svg viewBox='0 0 300 120' xmlns='http://www.w3.org/2000/svg'><circle cx='100' cy='60' r='28' fill='#60a5fa' opacity='0.4'/><circle cx='200' cy='60' r='28' fill='#14b8a6' opacity='0.4'/><circle cx='150' cy='60' r='6' fill='#f59e0b'/><text x='100' y='64' text-anchor='middle' fill='#0f172a' font-size='12'>A</text><text x='200' y='64' text-anchor='middle' fill='#0f172a' font-size='12'>B</text><text x='150' y='112' text-anchor='middle' fill='#64748b' font-size='11'>साझा इलेक्ट्रॉन जोड़ी (सहसंयोजक बंधन)</text></svg>","caption":"सहसंयोजक बंधन में दो परमाणु इलेक्ट्रॉन की जोड़ी साझा करते हैं"}$j$)
  ) as v(chapter_id, level_id, atom_key, atom_type, atom_order, title, body)
)
insert into mtb.atoms (chapter_id, level_id, atom_key, atom_type, atom_order, title, body, lang, exam_tags, subject_tag, difficulty, content_hash)
select s.chapter_id, s.level_id, s.atom_key, s.atom_type, s.atom_order, s.title, s.body, 'hi',
  case
    when s.level_id = 'govt_technical' then array['rrb-je-cbt1','rrb-je-cbt2','ssc-je-paper1']::text[]
    when s.level_id = 'govt_basic' then array['rrb-ntpc-graduate-cbt-1','rrb-ntpc-graduate-cbt-2','rrb-ntpc-ug-cbt-1','rrb-ntpc-ug-cbt-2']::text[]
    else '{}'::text[]
  end,
  'general-science', 'medium', md5(s.body::text)
from src s
on conflict do nothing;
